        },
        layout = "master",
        allow_tearing = false,
    },
    decoration = {
        rounding = 0,
        blur = {
            enabled = true,
            size = 5,
            passes = 0,
        },
    },
    animations = {
        enabled = true,
    },
})

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.animation({
    leaf = "windows",
